                keyword?: string;
                /** @description (optional) Repeatable `templates[]` array to restrict results to specific template types. Leave off to include all. */
                templates?: string;
                /** @description (optional) Repeatable `channels[]` array of channel slugs. When supplied, the endpoint returns real letters across those specific channels (published/sent newsletters, not the company's virtual-channel templates). Combine with `status`, `keyword`, and paging as usual. */
                channels?: string;
