    schedulePromotion: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                /**
                 * @example {
                 *       "campaignTitle": "Summer Sale 2026",
                 *       "channels": [
                 *         "an-example-channel"
                 *       ],
                 *       "headline": "50% off summer collection",
                 *       "contentText": "Limited-time offer on all summer items.",
                 *       "imageUrl": "https://cdn.example.com/summer-sale.png",
                 *       "imageAlternativeText": "Summer sale banner",
                 *       "promotionLink": "https://example.com/summer-sale",
                 *       "promoter": "Example Brand",
                 *       "dates": [
                 *         "2026-07-01"
                 *       ],
                 *       "isActive": true,
                 *       "isEvergreen": false,
                 *       "zone": "A",
                 *       "type": 2
                 *     }
                 */
                "application/json": {
                    /** @description Internal name of the campaign */
                    campaignTitle: string;
                    /** @description Slugs of channels to scope to. `null`/omitted means all channels. Required when `allChannels: false` is sent explicitly. */
                    channels?: string[];
                    /** @description Display headline of the ad */
                    headline?: string;
                    /** @description Body copy */
                    contentText?: string;
                    /** @description Publicly accessible image URL */
                    imageUrl?: string;
                    /** @description Alt text for accessibility */
                    imageAlternativeText?: string;
                    /** @description Click-through destination. Must be `http(s)`. */
                    promotionLink?: string;
                    /** @description Display name of the advertiser */
                    promoter?: string;
                    /** @description Y-m-d dates when the promotion runs. Ignored at send time if `isEvergreen: true`. */
                    dates?: string[];
                    /** @description `true` = scheduled/live, `false` = draft */
                    isActive: boolean;
                    /** @description `true` = always runs, `dates` are ignored at send time */
                    isEvergreen?: boolean;
                    /** @description Template position. One of `A`, `B`, `C`, `D`, `E`, `F`, `G`, `H`, `I`, `J`. Required unless `autoInject: true` is sent — there is no default, and omitting it without `autoInject` returns a 422 validation error. */
                    zone?: string;
                    /** @description Template type: `1`=Text only, `2`=Text & Image, `4`=Banner, `7`=HTML */
                    type: number;
                    /** @description When `true`, the promotion is auto-placed into every send at `autoInjectPosition` instead of a manually-chosen `zone`. When `true`, `zone` may be omitted but `autoInjectPosition` becomes required. Defaults to `false` (manual placement via `zone`). */
                    autoInject?: boolean;
                    /** @description 0-100 placement position, required when `autoInject: true`. Ignored for manual (non-auto-inject) promotions. */
                    autoInjectPosition?: number;
                };
            };
        };
        responses: {
            /** @description 201 Created */
            201: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "items": {
                     *         "promotionCollateralUid": "b2c3d4e5f6",
                     *         "campaignTitle": "Summer Sale 2026",
                     *         "channels": [
                     *           "an-example-channel"
                     *         ],
                     *         "allChannels": false,
                     *         "headline": "50% off summer collection",
                     *         "contentText": "Limited-time offer on all summer items.",
                     *         "imageUrl": "https://cdn.example.com/summer-sale.png",
                     *         "imageAlternativeText": "Summer sale banner",
                     *         "imageWidth": 0,
                     *         "imageHeight": 0,
                     *         "promotionLink": "https://example.com/summer-sale",
                     *         "promoter": "Example Brand",
                     *         "promotionServiceProviderId": 0,
                     *         "dates": [
                     *           "2026-07-01"
                     *         ],
                     *         "isActive": true,
                     *         "isInactive": false,
                     *         "isEvergreen": false,
                     *         "embedClicks": 0,
                     *         "zone": "A",
                     *         "type": 2,
                     *         "createdAt": "2026-06-04 17:30:00",
                     *         "updatedAt": "2026-06-04 17:30:00"
                     *       },
                     *       "message": "Promotion created successfully",
                     *       "total": 1
                     *     }
                     */
                    "application/json": {
                        items?: {
                            promotionCollateralUid?: string;
                            campaignTitle?: string;
                            channels?: string[];
                            allChannels?: boolean;
                            headline?: string;
                            contentText?: string;
                            imageUrl?: string;
                            imageAlternativeText?: string;
                            imageWidth?: number;
                            imageHeight?: number;
                            promotionLink?: string;
                            promoter?: string;
                            promotionServiceProviderId?: number;
                            dates?: string[];
                            isActive?: boolean;
                            isInactive?: boolean;
                            isEvergreen?: boolean;
                            embedClicks?: number;
                            zone?: string;
                            type?: number;
                            createdAt?: string;
                            updatedAt?: string;
                        };
                        message?: string;
                        total?: number;
                    };
                };
            };
        };
    };
